"""A very simple evaluator for a small subset of Forth."""

import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"-?\d+\Z")


def _is_number(token):
    return _NUMBER_RE.match(token) is not None


def _pop(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    return stack.pop()


def _add(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a + b)


def _subtract(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a - b)


def _multiply(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a * b)


def _divide(stack):
    b = _pop(stack)
    a = _pop(stack)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    stack.append(quotient)


def _dup(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    stack.append(stack[-1])


def _drop(stack):
    _pop(stack)


def _swap(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(b)
    stack.append(a)


def _over(stack):
    if len(stack) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    stack.append(stack[-2])


_BUILTINS = {
    "+": _add,
    "-": _subtract,
    "*": _multiply,
    "/": _divide,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _normalize(token):
    return token if _is_number(token) else token.lower()


def evaluate(input_data):
    stack = []
    user_words = {}

    def execute(tokens):
        for token in tokens:
            if _is_number(token):
                stack.append(int(token))
            elif token in user_words:
                execute(user_words[token])
            elif token in _BUILTINS:
                _BUILTINS[token](stack)
            else:
                raise ValueError("undefined operation")

    for line in input_data:
        tokens = [_normalize(token) for token in line.split()]
        if tokens and tokens[0] == ":":
            name = tokens[1]
            if _is_number(name):
                raise ValueError("illegal operation")
            body = []
            for token in tokens[2:]:
                if token == ";":
                    break
                if token in user_words:
                    body.extend(user_words[token])
                else:
                    body.append(token)
            user_words[name] = body
        else:
            execute(tokens)

    return stack
```

Wait — in the definition body expansion, `token in user_words` — tokens are already lowercased, and user_words keys are lowercase. Good.

